from rdkit import Chem
from rdkit.Chem import AllChem
sm='OC(C(F)(F)F)=Cc1ccccn1'
m=Chem.MolFromSmiles(sm)
for a in m.GetAtoms():print(a.GetIdx(),a.GetSymbol(),a.GetIsAromatic(),[x.GetIdx() for x in a.GetNeighbors()])
print(Chem.MolToSmiles(m))
r=Chem.RWMol()
for i in range(4):
 for atom in m.GetAtoms():
  b=Chem.Atom(atom.GetAtomicNum()); b.SetIsAromatic(atom.GetIsAromatic()); b.SetFormalCharge(atom.GetFormalCharge());r.AddAtom(b)
 for bond in m.GetBonds():r.AddBond(bond.GetBeginAtomIdx()+i*m.GetNumAtoms(),bond.GetEndAtomIdx()+i*m.GetNumAtoms(),bond.GetBondType())
for i in range(2):
 ge=r.AddAtom(Chem.Atom('Ge'))
 for j in (i*2, i*2+1):
  r.AddBond(ge,j*m.GetNumAtoms(),Chem.BondType.SINGLE)
  r.AddBond(j*m.GetNumAtoms()+11,ge,Chem.BondType.DATIVE)
au=r.AddAtom(Chem.Atom('Au'))
for i in range(2):r.AddBond(4*m.GetNumAtoms()+i,au,Chem.BondType.SINGLE)
p=r.GetMol()
try:
 Chem.SanitizeMol(p); print('sanitized',Chem.MolToSmiles(p))
except Exception as e: print('sanitize fails',e)
p=Chem.AddHs(p)
print('n atoms',p.GetNumAtoms())
params=AllChem.ETKDGv3();params.randomSeed=422;params.maxIterations=1000;params.useRandomCoords=True
status=AllChem.EmbedMolecule(p,params);print('embedding',status)
if status==0:
 from rdkit.Chem import rdMolTransforms
 for idx in range(2):
  print('ge',idx,[(x.GetIdx(),x.GetSymbol(),round(rdMolTransforms.GetBondLength(p.GetConformer(),x.GetIdx(),4*m.GetNumAtoms()+idx),2)) for x in p.GetAtomWithIdx(4*m.GetNumAtoms()+idx).GetNeighbors()])
 with open('initial.xyz','w') as f:
  f.write(f'{p.GetNumAtoms()}\nInitial geometry RDKit ETKDG for bis-germylene gold cation\n')
  for a in p.GetAtoms():
   pos=p.GetConformer().GetAtomPosition(a.GetIdx());f.write(f'{a.GetSymbol():2s} {pos.x:.8f} {pos.y:.8f} {pos.z:.8f}\n')
